def add(tp, qen, qvi, ans, wr, xe, xv, lvl=1):
    ws = []
    for w in wr:
        if w != ans and w not in ws: ws.append(w)
    assert len(ws) >= 3, (qen, ans, wr)
    items.append(dict(kind='mcq', q=B(qen, qvi), opts=O([ans] + ws[:3]), correct=0, explain=B(xe, xv), level=lvl, topic=TT[tp], src=B('Generated – computed binary/logic rule (EASA Q1-24…1-46)', 'Bổ sung – quy tắc nhị phân/logic được tính (EASA Q1-24…1-46)'), origin='bo_sung', fixed_order=False, check='script'))
